<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\JobApplication;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Validation\Rule;
class CompanyCandidateController extends Controller{private const STATUSES=['submitted','viewed','evaluating','shortlisted','interview','offer','hired','rejected'];public function index(Request $request):JsonResponse{$company=$this->company($request,false);$query=JobApplication::with('job:id,company_id,title,slug','user:id,name,email,phone')->whereHas('job',fn($q)=>$q->where('company_id',$company->id));if($request->filled('job_id'))$query->where('job_id',$request->integer('job_id'));if($request->filled('status'))$query->where('status',$request->string('status'));return response()->json(['data'=>$query->latest('applied_at')->get()]);}public function show(Request $request,JobApplication $application):JsonResponse{$this->owns($request,$application,false);$application->load('job:id,company_id,title,slug','user:id,name,email,phone','document:id,user_id,name,mime_type','messages.sender:id,name,account_type','interviews');$application->messages()->where('sender_id','!=',$request->user()->id)->whereNull('read_at')->update(['read_at'=>now()]);if($application->status==='submitted')$application->update(['status'=>'viewed']);return response()->json(['data'=>$application->fresh()->load('job:id,company_id,title,slug','user:id,name,email,phone','document:id,user_id,name,mime_type','messages.sender:id,name,account_type','interviews')]);}public function updateStatus(Request $request,JobApplication $application):JsonResponse{$this->owns($request,$application,true);$data=$request->validate(['status'=>['required',Rule::in(self::STATUSES)]]);abort_if(in_array($application->status,['withdrawn','hired','rejected']),422,'El proceso ya está cerrado.');$application->update($data);return response()->json(['data'=>$application,'message'=>'Estado de la candidatura actualizado.']);}public function message(Request $request,JobApplication $application):JsonResponse{$this->owns($request,$application,true);$data=$request->validate(['body'=>['required','string','max:5000']]);$message=$application->messages()->create(['sender_id'=>$request->user()->id,'body'=>$data['body']]);return response()->json(['data'=>$message->load('sender:id,name,account_type'),'message'=>'Mensaje enviado.'],201);}public function interview(Request $request,JobApplication $application):JsonResponse{$this->owns($request,$application,true);$data=$request->validate(['title'=>['required','string','max:150'],'scheduled_at'=>['required','date','after:now'],'duration_minutes'=>['required','integer','min:15','max:480'],'format'=>['required',Rule::in(['video','phone','in_person'])],'location_or_link'=>['nullable','string','max:500'],'notes'=>['nullable','string','max:2000']]);$interview=$application->interviews()->create([...$data,'created_by'=>$request->user()->id,'status'=>'scheduled']);$application->update(['status'=>'interview']);return response()->json(['data'=>$interview,'message'=>'Entrevista programada.'],201);}public function document(Request $request,JobApplication $application){$this->owns($request,$application,false);$document=$application->document;abort_unless($document&&Storage::disk('local')->exists($document->path),404);return Storage::disk('local')->download($document->path,$document->name);}private function company(Request $request,bool $write){abort_unless($request->user()->account_type==='company',403);$company=$request->user()->companies()->wherePivot('status','active')->first();abort_unless($company,422);$role=$company->members()->whereKey($request->user()->id)->first()?->pivot->role;if($write)abort_unless(in_array($role,['owner','admin','recruiter']),403);return $company;}private function owns(Request $request,JobApplication $application,bool $write):void{$company=$this->company($request,$write);abort_unless($application->job()->where('company_id',$company->id)->exists(),404);}}
